<?php
require __DIR__.'/../includes/core.php';header('Referrer-Policy: no-referrer');header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: no-store, private');
$token=(string)($_GET['token']??$_POST['token']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$token)){http_response_code(404);exit('Link not found.');}
$share=one('SELECT * FROM evaluation_bulk_shares WHERE token_hash=? AND revoked_at IS NULL AND expires_at>NOW()',[hash('sha256',$token)]);if(!$share){http_response_code(404);exit('This link is invalid, expired or revoked.');}
$where="a.status='submitted'";$args=[];if($share['cycle_id']!==null){$where.=' AND a.cycle_id=?';$args[]=$share['cycle_id'];}if($share['module_id']!==null){$where.=' AND a.module_id=?';$args[]=$share['module_id'];}
$rows=all("SELECT a.id,a.submitted_at,m.name module_name,t.name teacher,s.name session_name,c.term FROM assignments a JOIN modules m ON m.id=a.module_id JOIN users t ON t.id=a.subject_id JOIN evaluation_cycles c ON c.id=a.cycle_id JOIN academic_sessions s ON s.id=c.session_id WHERE $where ORDER BY t.name,m.name,a.id",$args);
$id=(int)($_GET['id']??$_POST['assignment_id']??0);$selected=null;foreach($rows as $r){if((int)$r['id']===$id){$selected=$r;break;}}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{
 if(!$selected)throw new Exception('Assessment not available.');
 $name=trim((string)($_POST['assessor_name']??''));$remark=trim((string)($_POST['remarks']??''));
 if(mb_strlen($name)<3||mb_strlen($name)>150||mb_strlen($remark)<10||mb_strlen($remark)>5000)throw new Exception('Enter a name and a remark of 10–5,000 characters.');
 sql('INSERT INTO evaluation_bulk_remarks(share_id,assignment_id,assessor_name,remarks) VALUES (?,?,?,?)',[$share['id'],$id,$name,$remark]);header('Location: '.url('external/all_reviews.php?token='.$token.'&id='.$id));exit;
 }catch(Throwable $e){$error=$e->getCode()==='23000'?'A remark has already been submitted for this assessment through this link.':$e->getMessage();}}
$remarks=all('SELECT * FROM evaluation_bulk_remarks WHERE share_id=?',[$share['id']]);$byId=[];foreach($remarks as $r)$byId[$r['assignment_id']]=$r;
ob_start();?><div class="card"><h2>External assessment review portal</h2><p>Confidential school assessment records. Authorized assessors only. This link expires on <?=h($share['expires_at'])?>.</p><h3><?=count($rows)?> submitted assessments</h3><div class="tablewrap"><table><tr><th>Teacher</th><th>Module</th><th>Academic period</th><th>Review</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['teacher'])?></td><td><?=h($r['module_name'])?></td><td><?=h($r['session_name'].' '.$r['term'])?></td><td><a href="<?=url('external/all_reviews.php?token='.$token.'&id='.$r['id'])?>">View assessment<?=isset($byId[$r['id']])?' (remarked)':''?></a></td></tr><?php endforeach;?></table></div></div>
<?php if($selected):$sc=score_assignment($id);$comments=one('SELECT * FROM evaluation_comments WHERE assignment_id=?',[$id])??[];$ratings=all('SELECT s.title section_title,c.title criterion_title,r.rating,o.label rating_label FROM responses r JOIN criteria c ON c.id=r.criterion_id JOIN template_sections s ON s.id=c.section_id JOIN rating_options o ON o.module_id=s.module_id AND o.rating=r.rating WHERE r.assignment_id=? ORDER BY s.sort_order,s.id,c.sort_order,c.id',[$id]);?><div class="card"><h2><?=h($selected['teacher'].' — '.$selected['module_name'])?></h2><h3><?=number_format($sc['weighted_percent'],2)?>%</h3><h4>Section results</h4><div class="tablewrap"><table><tr><th>Section</th><th>Score</th><th>Weight</th></tr><?php foreach($sc['sections'] as $sec):?><tr><td><?=h($sec['section'])?></td><td><?=number_format($sec['percent'],2)?>%</td><td><?=number_format($sec['weight'],2)?>%</td></tr><?php endforeach;?></table></div><h4>Assessment criteria</h4><div class="tablewrap"><table><tr><th>Section</th><th>Indicator</th><th>Rating</th></tr><?php foreach($ratings as $r):?><tr><td><?=h($r['section_title'])?></td><td><?=h($r['criterion_title'])?></td><td><?=h($r['rating'].' — '.$r['rating_label'])?></td></tr><?php endforeach;?></table></div><?php foreach(['strengths'=>'Strengths','improvements'=>'Improvements','impression'=>'Impression','remarks'=>'Evaluator remarks'] as $key=>$label):?><?php if(!empty($comments[$key])):?><h4><?=h($label)?></h4><p><?=nl2br(h($comments[$key]))?></p><?php endif;?><?php endforeach;?></div><div class="card"><h3>External assessor remark</h3><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if(isset($byId[$id])):$remark=$byId[$id];?><p><strong><?=h($remark['assessor_name'])?></strong> — <?=h($remark['created_at'])?></p><p><?=nl2br(h($remark['remarks']))?></p><?php else:?><form method="post"><?=token()?><input type="hidden" name="token" value="<?=h($token)?>"><input type="hidden" name="assignment_id" value="<?=$id?>"><label>Your full name</label><input name="assessor_name" maxlength="150" required><label>Professional remark for this assessment</label><textarea name="remarks" rows="6" minlength="10" maxlength="5000" required></textarea><p><button onclick="return confirm('Submit this remark? It cannot be edited afterward.')">Submit remark</button></p></form><?php endif;?></div><?php endif;?><?php layout('External assessment review portal',ob_get_clean());
